package pgi3pilot

import "testing"

func TestNormalizeLabel(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  string
	}{
		{"empty", "", ""},
		{"unchanged", "Keep  CaSe", "Keep  CaSe"},
		{"spaces", "  Keep  Case  ", "Keep  Case"},
		{"ASCII whitespace", "\t\n\r\v\f Keep\tCaSe \r\n\t", "Keep\tCaSe"},
		{"Unicode boundaries", "\u00a0\u2003Keep\t\tCaSe\u202f\u3000", "Keep\t\tCaSe"},
		{"leading Unicode", "\u0085\u1680Keep", "Keep"},
		{"trailing Unicode", "CaSe\u2028\u2029", "CaSe"},
		{"interior content", "\u2003Élan\t \u00a0\u2003CaSe\n世界\u3000", "Élan\t \u00a0\u2003CaSe\n世界"},
		{"whitespace only", " \t\n\u0085\u00a0\u1680\u2003\u2028\u2029\u202f\u3000", ""},
		{"non-whitespace boundaries", "\u200bKeep\tCaSe\ufeff", "\u200bKeep\tCaSe\ufeff"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := NormalizeLabel(tt.input); got != tt.want {
				t.Errorf("NormalizeLabel(%q) = %q, want %q", tt.input, got, tt.want)
			}
		})
	}
}

