package pgi3pilot

import "testing"

func TestNormalizeLabel(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  string
	}{
		{name: "ASCII spaces", input: "  Keep  Case  ", want: "Keep  Case"},
		{name: "Unicode boundaries", input: "\u00a0\u2003Keep Case\u202f\u3000", want: "Keep Case"},
		{name: "ASCII whitespace", input: "\t\r\n Keep Case \v\f", want: "Keep Case"},
		{name: "interior content", input: "\u2003MiXeD\t\t  CaSe\u00a0Label\u3000", want: "MiXeD\t\t  CaSe\u00a0Label"},
		{name: "unchanged", input: "MiXeD\t Label", want: "MiXeD\t Label"},
		{name: "empty", input: "", want: ""},
		{name: "only whitespace", input: " \t\n\u0085\u00a0\u2003\u2028\u2029\u202f\u3000", want: ""},
		{name: "non-whitespace boundaries", input: "\u200bKeep Case\u200b", want: "\u200bKeep Case\u200b"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := NormalizeLabel(tt.input); got != tt.want {
				t.Errorf("NormalizeLabel(%q) = %q, want %q", tt.input, got, tt.want)
			}
		})
	}
}
